/**
 * Cartesia AI Text-to-Speech client.
 * Speech is generated by the backend so the API key and locked voice
 * configuration never ship to the browser.
 */
import { API_BASE_URL } from './api'

const audioCache = new Map()
const inflightPromises = new Map()

/**
 * Strips HTML tags, Markdown links, and excess whitespace to produce clean speech text.
 */
export function cleanTextForSpeech(rawText = '') {
  if (!rawText) return ''
  return rawText
    .replace(/<[^>]*>/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&nbsp;/g, ' ')
    .replace(/!\[[^\]]*\]\([^)]*\)/g, '')
    .replace(/\[([^\]]+)\]\([^)]*\)/g, '$1')
    .replace(/https?:\/\/\S+/g, '')
    .replace(/—|–/g, ', ')
    .replace(/\s+/g, ' ')
    .trim()
}

/**
 * Prepares the complete spoken narrative for an article
 */
export function buildArticleNarrationText(article) {
  if (!article) return ''

  const parts = []

  if (article.title) {
    parts.push(cleanTextForSpeech(article.title) + '.')
  }

  if (article.quote) {
    parts.push(cleanTextForSpeech(article.quote))
  }

  if (Array.isArray(article.paragraphs) && article.paragraphs.length > 0) {
    article.paragraphs.forEach((p) => {
      const cleaned = cleanTextForSpeech(p)
      if (cleaned) parts.push(cleaned)
    })
  } else if (article.contentHtml) {
    const cleaned = cleanTextForSpeech(article.contentHtml)
    if (cleaned) parts.push(cleaned)
  } else if (article.excerpt) {
    const cleaned = cleanTextForSpeech(article.excerpt)
    if (cleaned) parts.push(cleaned)
  }

  return parts.join(' ')
}

async function readErrorMessage(response) {
  const fallback = 'Failed to generate voice narration. Please try again.'
  const contentType = response.headers.get('content-type') || ''
  try {
    if (contentType.includes('application/json')) {
      const data = await response.json()
      return data.error || fallback
    }
    const text = await response.text()
    return text || fallback
  } catch {
    return fallback
  }
}

/**
 * Requests speech from the backend TTS endpoint using the locked Cartesia voice.
 *
 * @param {Object} options
 * @param {string} options.text - Text to speak
 * @param {string} [options.articleId] - Optional cache key
 * @returns {Promise<{ audioUrl: string, cached: boolean }>}
 */
export async function generateCartesiaSpeech({ text, articleId }) {
  const cleanTranscript = cleanTextForSpeech(text)
  if (!cleanTranscript) {
    throw new Error('No readable text available to narrate.')
  }

  const cacheKey = articleId ? String(articleId) : cleanTranscript.slice(0, 80)

  if (audioCache.has(cacheKey)) {
    return {
      audioUrl: audioCache.get(cacheKey),
      cached: true,
    }
  }

  if (inflightPromises.has(cacheKey)) {
    return inflightPromises.get(cacheKey)
  }

  const fetchPromise = (async () => {
    try {
      const controller = new AbortController()
      const timeoutId = setTimeout(() => controller.abort(), 180000)

      let response
      try {
        response = await fetch(`${API_BASE_URL}/tts/speech`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ text: cleanTranscript }),
          signal: controller.signal,
        })
      } catch (err) {
        if (err.name === 'AbortError') {
          throw new Error('Voice generation timed out. Please try again.')
        }
        throw new Error('Unable to reach the voice service. Please check your connection.')
      } finally {
        clearTimeout(timeoutId)
      }

      if (!response.ok) {
        throw new Error(await readErrorMessage(response))
      }

      const audioBlob = await response.blob()
      if (!audioBlob || audioBlob.size === 0) {
        throw new Error('Voice service returned empty audio. Please try again.')
      }

      const typedBlob =
        audioBlob.type && audioBlob.type.startsWith('audio/')
          ? audioBlob
          : new Blob([audioBlob], { type: 'audio/mpeg' })
      const audioUrl = URL.createObjectURL(typedBlob)
      audioCache.set(cacheKey, audioUrl)

      return {
        audioUrl,
        cached: false,
      }
    } finally {
      inflightPromises.delete(cacheKey)
    }
  })()

  inflightPromises.set(cacheKey, fetchPromise)
  return fetchPromise
}

/**
 * Background prefetch utility to warm cache before the user clicks Play.
 */
export function prefetchCartesiaSpeech({ text, articleId }) {
  if (!text) return Promise.resolve(null)
  return generateCartesiaSpeech({ text, articleId })
    .then((res) => res?.audioUrl || null)
    .catch((err) => {
      console.debug('Background prefetch idle:', err)
      return null
    })
}
